-- Hand-authored questions for five additional browse subjects.
with catalog as materialized (
 select * from jsonb_to_recordset($subjects$
[
 {"slug":"extra-duck-billed-platypus","title":"Platypus","subject":"Animals","kind":"what","prompt":"Which Australian mammal has a broad bill, webbed feet, and lays eggs?","presentation":{"mechanic":"text"},"solution":{"label":"Platypus","aliases":["Platypus","duck-billed platypus","duck billed platypus"]},"explanation":"The platypus is an egg-laying mammal that spends much of its time hunting in fresh water.","source_title":"San Diego Zoo Wildlife Alliance: Platypus","source_url":"https://animals.sandiegozoo.org/animals/platypus"},
 {"slug":"extra-echidna","title":"Echidna","subject":"Animals","kind":"what","prompt":"Which spiny Australian mammal belongs to the egg-laying group called monotremes?","presentation":{"mechanic":"text"},"solution":{"label":"Echidna","aliases":["Echidna","spiny anteater"]},"explanation":"Echidnas are monotremes. Their spines and long snouts distinguish them from the other living monotreme, the platypus.","source_title":"San Diego Zoo Wildlife Alliance: Echidna","source_url":"https://animals.sandiegozoo.org/animals/echidna"},
 {"slug":"extra-capybara","title":"Capybara","subject":"Animals","kind":"what","prompt":"What is the largest living rodent?","presentation":{"mechanic":"text"},"solution":{"label":"Capybara","aliases":["Capybara"]},"explanation":"The capybara is a large, water-loving relative of the guinea pig.","source_title":"San Diego Zoo Wildlife Alliance: Capybara","source_url":"https://animals.sandiegozoo.org/animals/capybara"},
 {"slug":"extra-okapi","title":"Okapi","subject":"Animals","kind":"what","prompt":"Which rainforest relative of the giraffe has black-and-white striped legs?","presentation":{"mechanic":"text"},"solution":{"label":"Okapi","aliases":["Okapi","forest giraffe"]},"explanation":"Despite its zebra-like leg stripes, the okapi belongs to the giraffe family.","source_title":"San Diego Zoo Wildlife Alliance: Okapi","source_url":"https://animals.sandiegozoo.org/animals/okapi"},
 {"slug":"extra-emu","title":"Emu","subject":"Animals","kind":"what","prompt":"Which Australian flightless bird is the second-largest living bird after the ostrich?","presentation":{"mechanic":"text"},"solution":{"label":"Emu","aliases":["Emu"]},"explanation":"Emus are large flightless birds native to Australia.","source_title":"San Diego Zoo Wildlife Alliance: Emu","source_url":"https://animals.sandiegozoo.org/animals/emu"},
 {"slug":"extra-komodo-dragon","title":"Komodo dragon","subject":"Animals","kind":"what","prompt":"What is the world’s largest living lizard?","presentation":{"mechanic":"text"},"solution":{"label":"Komodo dragon","aliases":["Komodo dragon","Komodo monitor"]},"explanation":"Komodo dragons are native to a small group of Indonesian islands.","source_title":"Smithsonian National Zoo: Komodo dragon","source_url":"https://nationalzoo.si.edu/animals/komodo-dragon"},
 {"slug":"extra-narwhal","title":"Narwhal","subject":"Animals","kind":"what","prompt":"Which Arctic whale is known for a long spiral tusk that grows from a tooth?","presentation":{"mechanic":"text"},"solution":{"label":"Narwhal","aliases":["Narwhal"]},"explanation":"In most male narwhals, one upper tooth grows forward into a long spiral tusk.","source_title":"NOAA Fisheries: Narwhal","source_url":"https://www.fisheries.noaa.gov/species/narwhal"},
 {"slug":"extra-blue-whale","title":"Blue whale","subject":"Animals","kind":"what","prompt":"Which whale is the largest living animal?","presentation":{"mechanic":"text"},"solution":{"label":"Blue whale","aliases":["Blue whale"]},"explanation":"Blue whales grow larger than any other living animal and feed mainly on krill.","source_title":"NOAA Fisheries: Blue whale","source_url":"https://www.fisheries.noaa.gov/species/blue-whale"},
 {"slug":"extra-red-panda","title":"Red panda","subject":"Animals","kind":"what","prompt":"What plant do red pandas grasp with their wrist-bone pseudo-thumbs and eat in large quantities?","presentation":{"mechanic":"text"},"solution":{"label":"Bamboo","aliases":["Bamboo"]},"explanation":"A modified wrist bone helps red pandas grip bamboo shoots and leaves.","source_title":"Smithsonian National Zoo: Red panda","source_url":"https://nationalzoo.si.edu/animals/red-panda"},
 {"slug":"extra-giant-anteater","title":"Giant anteater","subject":"Animals","kind":"what","prompt":"Which South American mammal uses a very long tongue to collect ants and termites?","presentation":{"mechanic":"text"},"solution":{"label":"Giant anteater","aliases":["Giant anteater"]},"explanation":"The giant anteater uses its narrow snout and long tongue to reach prey in insect nests.","source_title":"Smithsonian National Zoo: Giant anteater","source_url":"https://nationalzoo.si.edu/animals/giant-anteater"},
 {"slug":"extra-octopus-camouflage","title":"Octopus camouflage","subject":"Animals","kind":"what","prompt":"What is the term for an octopus changing its appearance to blend in with its surroundings?","presentation":{"mechanic":"text"},"solution":{"label":"Camouflage","aliases":["Camouflage"]},"explanation":"A giant Pacific octopus can alter its skin color to blend in with nearby rocks.","source_title":"Monterey Bay Aquarium: Giant Pacific octopus","source_url":"https://www.montereybayaquarium.org/visit/exhibits/giant-pacific-octopus"},
 {"slug":"extra-sea-otter-kelp","title":"Sea otters and kelp","subject":"Animals","kind":"why","prompt":"Which facts explain how sea otters help protect kelp forests?","presentation":{"options":[{"id":"step-1","label":"Sea otters prey on sea urchins."},{"id":"step-2","label":"Sea urchins graze on kelp."},{"id":"step-3","label":"Kelp grows from nutrients made by otter fur."},{"id":"step-4","label":"Sea urchins build reefs that shade out kelp."}],"mechanic":"evidence"},"solution":{"correct":["step-1","step-2"],"label":"Otters reduce grazing pressure","mechanic":"evidence"},"explanation":"Otters eat sea urchins. When fewer urchins are left to graze, more kelp can survive.","source_title":"Monterey Bay Aquarium: Sea otter","source_url":"https://www.montereybayaquarium.org/animals-the-ocean/animals-a-to-z/sea-otter"},
 {"slug":"extra-monarch-life-cycle","title":"Monarch life cycle","subject":"Animals","kind":"how","prompt":"Arrange a monarch butterfly’s life stages from egg to adult.","presentation":{"options":[{"id":"step-1","label":"Egg"},{"id":"step-2","label":"Caterpillar"},{"id":"step-3","label":"Chrysalis"},{"id":"step-4","label":"Adult butterfly"}]},"solution":{"correct":["step-1","step-2","step-3","step-4"],"label":"Egg, caterpillar, chrysalis, adult"},"explanation":"The caterpillar that hatches from the egg feeds and grows before becoming a chrysalis.","source_title":"U.S. Fish & Wildlife Service: Monarch","source_url":"https://www.fws.gov/species/monarch-danaus-plexippus"},
 {"slug":"extra-green-turtle-hatchling","title":"Green turtle nesting","subject":"Animals","kind":"how","prompt":"Arrange what happens from a green turtle laying her eggs to the hatchlings reaching the sea.","presentation":{"options":[{"id":"step-1","label":"The mother lays eggs in the sand."},{"id":"step-2","label":"The embryos develop inside the eggs."},{"id":"step-3","label":"The eggs hatch."},{"id":"step-4","label":"The hatchlings move toward the water."}]},"solution":{"correct":["step-1","step-2","step-3","step-4"],"label":"Laying, incubation, hatching, the sea"},"explanation":"The eggs incubate in beach sand. Once the hatchlings emerge, they make their way to the water.","source_title":"NOAA Fisheries: Green turtle","source_url":"https://www.fisheries.noaa.gov/species/green-turtle"},
 {"slug":"extra-mercury-orbit","title":"Mercury orbit","subject":"Space & Astronomy","kind":"what","prompt":"Which planet takes about 88 Earth days to orbit the Sun?","presentation":{"mechanic":"text"},"solution":{"label":"Mercury","aliases":["Mercury"]},"explanation":"Mercury travels around the Sun in less than three Earth months.","source_title":"NASA: Mercury facts","source_url":"https://science.nasa.gov/mercury/facts/"},
 {"slug":"extra-olympus-mons","title":"Olympus Mons","subject":"Space & Astronomy","kind":"what","prompt":"Which planet is home to Olympus Mons?","presentation":{"mechanic":"text"},"solution":{"label":"Mars","aliases":["Mars"]},"explanation":"Olympus Mons is a vast shield volcano on Mars.","source_title":"NASA: Mars facts","source_url":"https://science.nasa.gov/mars/facts/"},
 {"slug":"extra-uranus-tilt","title":"Uranus axial tilt","subject":"Space & Astronomy","kind":"what","prompt":"Which planet has an axial tilt of about 98 degrees and appears to spin on its side?","presentation":{"mechanic":"text"},"solution":{"label":"Uranus","aliases":["Uranus"]},"explanation":"Uranus rotates with an extreme tilt of nearly 98 degrees.","source_title":"NASA: Uranus facts","source_url":"https://science.nasa.gov/uranus/facts/"},
 {"slug":"extra-ceres","title":"Ceres","subject":"Space & Astronomy","kind":"what","prompt":"Which dwarf planet is the largest object in the main asteroid belt between Mars and Jupiter?","presentation":{"mechanic":"text"},"solution":{"label":"Ceres","aliases":["Ceres"]},"explanation":"Ceres is the largest body in the main asteroid belt.","source_title":"NASA: Ceres facts","source_url":"https://science.nasa.gov/dwarf-planets/ceres/facts/"},
 {"slug":"extra-jupiter-red-spot","title":"Jupiter’s Great Red Spot","subject":"Space & Astronomy","kind":"what","prompt":"On which planet is the Great Red Spot, a long-lived storm?","presentation":{"mechanic":"text"},"solution":{"label":"Jupiter","aliases":["Jupiter"]},"explanation":"Astronomers have observed the Great Red Spot on Jupiter for centuries.","source_title":"NASA: Jupiter facts","source_url":"https://science.nasa.gov/jupiter/jupiter-facts/"},
 {"slug":"extra-venus-greenhouse","title":"Venus and its greenhouse effect","subject":"Space & Astronomy","kind":"why","prompt":"Why is the surface of Venus hotter than Mercury’s even though Venus is farther from the Sun?","presentation":{"options":[{"id":"step-1","label":"Venus has a thick atmosphere rich in carbon dioxide."},{"id":"step-2","label":"Greenhouse gases slow the escape of heat from Venus."},{"id":"step-3","label":"Venus receives more sunlight because it orbits closer."},{"id":"step-4","label":"Venus is heated by a star of its own."}],"mechanic":"evidence"},"solution":{"correct":["step-1","step-2"],"label":"A strong greenhouse effect","mechanic":"evidence"},"explanation":"The thick atmosphere keeps Venus’s surface very hot by trapping heat through the greenhouse effect.","source_title":"NASA: Venus facts","source_url":"https://science.nasa.gov/venus/venus-facts/"},
 {"slug":"extra-inner-planets","title":"Inner planets","subject":"Space & Astronomy","kind":"how","prompt":"Arrange the four rocky planets from nearest to farthest from the Sun.","presentation":{"options":[{"id":"step-1","label":"Mercury"},{"id":"step-2","label":"Venus"},{"id":"step-3","label":"Earth"},{"id":"step-4","label":"Mars"}]},"solution":{"correct":["step-1","step-2","step-3","step-4"],"label":"Mercury, Venus, Earth, Mars"},"explanation":"The rocky planets all orbit inside the main asteroid belt.","source_title":"NASA: Solar system facts","source_url":"https://science.nasa.gov/solar-system/solar-system-facts/"},
 {"slug":"extra-kimjang","title":"Kimjang","subject":"Food & Drink","kind":"what","prompt":"What fermented food do communities make and share in the Korean tradition of kimjang?","presentation":{"mechanic":"text"},"solution":{"label":"Kimchi","aliases":["Kimchi"]},"explanation":"Kimjang brings people together to prepare batches of kimchi, often in late autumn.","source_title":"UNESCO: Kimjang","source_url":"https://ich.unesco.org/en/RL/kimjang-making-and-sharing-kimchi-in-the-republic-of-korea-00881"},
 {"slug":"extra-washoku","title":"Washoku","subject":"Food & Drink","kind":"what","prompt":"What name does UNESCO use for Japan’s traditional dietary culture, especially as practiced during New Year?","presentation":{"mechanic":"text"},"solution":{"label":"Washoku","aliases":["Washoku"]},"explanation":"Washoku includes shared knowledge about food preparation, presentation, and seasonal ingredients.","source_title":"UNESCO: Washoku","source_url":"https://ich.unesco.org/en/RL/washoku-traditional-dietary-cultures-of-the-japanese-notably-for-the-celebration-of-the-new-year-00869"},
 {"slug":"extra-baguette","title":"Baguette bread","subject":"Food & Drink","kind":"what","prompt":"What long French loaf is the focus of a UNESCO listing for artisanal breadmaking and culture?","presentation":{"mechanic":"text"},"solution":{"label":"Baguette","aliases":["Baguette","French baguette"]},"explanation":"The UNESCO entry covers the craft of baking baguettes and the customs around buying and eating them.","source_title":"UNESCO: Baguette bread","source_url":"https://ich.unesco.org/en/decisions/17.COM/7.B.8"},
 {"slug":"extra-pizzaiuolo","title":"Neapolitan pizzaiuolo","subject":"Food & Drink","kind":"what","prompt":"What food is made by a pizzaiuolo in the Neapolitan tradition recognized by UNESCO?","presentation":{"mechanic":"text"},"solution":{"label":"Pizza","aliases":["Pizza","Neapolitan pizza"]},"explanation":"The Neapolitan tradition involves working the dough and baking the pizza in a wood-fired oven.","source_title":"UNESCO: Art of Neapolitan pizzaiuolo","source_url":"https://ich.unesco.org/en/decisions/12.COM/11.B.17"},
 {"slug":"extra-couscous-preparation","title":"Couscous preparation","subject":"Food & Drink","kind":"how","prompt":"Arrange these traditional couscous preparation steps from grain to cooking.","presentation":{"options":[{"id":"step-1","label":"Grind the cereal into semolina."},{"id":"step-2","label":"Roll the semolina into small grains."},{"id":"step-3","label":"Steam the rolled grains."}]},"solution":{"correct":["step-1","step-2","step-3"],"label":"Grind, roll, steam"},"explanation":"Traditional couscous is made by processing cereal into semolina, rolling it, then steaming it.","source_title":"UNESCO: Couscous traditions","source_url":"https://ich.unesco.org/en/RL/couscous-knowledge-know-how-and-practices-pertaining-to-the-production-and-consumption-of-couscous-01602"},
 {"slug":"extra-starry-night","title":"The Starry Night","subject":"Art & Design","kind":"who","prompt":"Who painted The Starry Night in Saint-Rémy in 1889?","presentation":{"mechanic":"text"},"solution":{"label":"Vincent van Gogh","aliases":["Vincent van Gogh","Van Gogh"]},"explanation":"Van Gogh painted The Starry Night while living in Saint-Rémy, France.","source_title":"MoMA: The Starry Night","source_url":"https://www.moma.org/collection/works/79802"},
 {"slug":"extra-great-wave","title":"The Great Wave","subject":"Art & Design","kind":"who","prompt":"Who created the Japanese woodblock print commonly called The Great Wave?","presentation":{"mechanic":"text"},"solution":{"label":"Katsushika Hokusai","aliases":["Katsushika Hokusai","Hokusai"]},"explanation":"Hokusai made The Great Wave for his series of views of Mount Fuji.","source_title":"The Met: Under the Wave off Kanagawa","source_url":"https://www.metmuseum.org/art/collection/search/45434"},
 {"slug":"extra-persistence-of-memory","title":"The Persistence of Memory","subject":"Art & Design","kind":"who","prompt":"Who painted The Persistence of Memory, famous for its melting watches?","presentation":{"mechanic":"text"},"solution":{"label":"Salvador Dalí","aliases":["Salvador Dalí","Salvador Dali","Dalí","Dali"]},"explanation":"Dalí painted The Persistence of Memory in 1931.","source_title":"MoMA: The Persistence of Memory","source_url":"https://www.moma.org/momaorg/shared/flattened_pages/moma_learning/salvador-dali-the-persistence-of-memory-1931/"},
 {"slug":"extra-mona-lisa-artist","title":"Mona Lisa artist","subject":"Art & Design","kind":"who","prompt":"Who painted the Mona Lisa on display at the Louvre?","presentation":{"mechanic":"text"},"solution":{"label":"Leonardo da Vinci","aliases":["Leonardo da Vinci","Leonardo","Da Vinci"]},"explanation":"The Louvre identifies Leonardo da Vinci as the artist.","source_title":"Louvre: The Salle des États","source_url":"https://musee.louvre.fr/en/explore/the-palace/from-the-mona-lisa-to-the-wedding-feast-at-cana"},
 {"slug":"extra-mona-lisa-panel","title":"Mona Lisa painting support","subject":"Art & Design","kind":"what","prompt":"What type of wood forms the panel on which the Mona Lisa was painted?","presentation":{"mechanic":"text"},"solution":{"label":"Poplar","aliases":["Poplar","Poplar wood"]},"explanation":"The painting is on a poplar panel, which requires special conservation care.","source_title":"Louvre: The Salle des États","source_url":"https://musee.louvre.fr/en/explore/the-palace/from-the-mona-lisa-to-the-wedding-feast-at-cana"},
 {"slug":"extra-chess-knight","title":"Chess knight","subject":"Games & Hobbies","kind":"what","prompt":"Which chess piece makes a move shaped like an L?","presentation":{"mechanic":"text"},"solution":{"label":"Knight","aliases":["Knight","The knight"]},"explanation":"A knight moves two squares along one axis and one square along the other.","source_title":"FIDE Laws of Chess","source_url":"https://handbook.fide.com/chapter/E012023"},
 {"slug":"extra-chess-stalemate","title":"Chess stalemate","subject":"Games & Hobbies","kind":"what","prompt":"What is it called in chess when the player to move has no legal move and their king is out of check?","presentation":{"mechanic":"text"},"solution":{"label":"Stalemate","aliases":["Stalemate"]},"explanation":"Stalemate ends the game as a draw.","source_title":"FIDE Laws of Chess","source_url":"https://handbook.fide.com/chapter/E012023"},
 {"slug":"extra-chess-castling-conditions","title":"Chess castling conditions","subject":"Games & Hobbies","kind":"why","prompt":"Which conditions prevent a player from castling on the chosen side in standard chess?","presentation":{"options":[{"id":"step-1","label":"The king would pass through a square under attack."},{"id":"step-2","label":"A piece stands between the king and the chosen rook."},{"id":"step-3","label":"A pawn was captured earlier in the game."},{"id":"step-4","label":"The player is behind in material."}],"mechanic":"evidence"},"solution":{"correct":["step-1","step-2"],"label":"Attacked king’s path or a blocked path","mechanic":"evidence"},"explanation":"Castling is disallowed when the king travels through an attacked square or another piece blocks the space between the king and rook.","source_title":"FIDE Laws of Chess","source_url":"https://handbook.fide.com/chapter/E012023"},
 {"slug":"extra-go-liberties","title":"Liberties in Go","subject":"Games & Hobbies","kind":"what","prompt":"What are the empty intersections directly adjacent to a stone or its connected group called in Go?","presentation":{"mechanic":"text"},"solution":{"label":"Liberties","aliases":["Liberties","Liberty"]},"explanation":"A liberty is an adjacent empty intersection reached horizontally or vertically.","source_title":"American Go Association: Official rules","source_url":"https://www.usgo-archive.org/files/pdf/completerules.pdf"},
 {"slug":"extra-go-board","title":"Go board size","subject":"Games & Hobbies","kind":"what","prompt":"How many lines run in each direction on a full-sized Go board?","presentation":{"mechanic":"text"},"solution":{"label":"19","aliases":["19","nineteen","19x19","19 x 19","19×19"]},"explanation":"A full-sized Go board uses a grid of 19 horizontal and 19 vertical lines.","source_title":"American Go Association: Official rules","source_url":"https://www.usgo-archive.org/files/pdf/completerules.pdf"}
]
$subjects$::jsonb) as c(
  slug text,title text,subject text,kind text,prompt text,presentation jsonb,
  solution jsonb,explanation text,source_title text,source_url text
 )
), inserted_topics as (
 insert into public.topics(slug,title,subject)
 select slug,title,subject from catalog on conflict(slug) do nothing returning id,slug
), topic_ids as (
 select id,slug from inserted_topics
 union all
 select t.id,t.slug from public.topics t join catalog c on c.slug=t.slug
)
insert into public.questions(topic_id,kind,prompt,presentation,solution,explanation,source_title,source_url,status,verified_at)
select t.id,c.kind,c.prompt,c.presentation,c.solution,c.explanation,c.source_title,c.source_url,
 case when cardinality(public.whirl_validate(c.kind,c.presentation,c.solution,c.explanation,c.source_url,c.source_title))=0
      then 'published' else 'invalid catalog row' end,
 '2026-11-24T00:00:00Z'::timestamptz
from catalog c join topic_ids t on t.slug=c.slug
where not exists(select 1 from public.questions q where q.topic_id=t.id and q.kind=c.kind)
on conflict do nothing;
